import{_ as o,I as e,o as h,c,b6 as i,j as a,J as l,w as t,a as n}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"تطوير نظام الامتحانات عبر الإنترنت والإدارة — تطبيق عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/exam-management-express/index.md","filePath":"ar-sa/stage-2/assignments/exam-management-express/index.md"}'),b={name:"ar-sa/stage-2/assignments/exam-management-express/index.md"},u={style:{margin:"32px 0"}};function g(k,s,m,x,f,_){const p=e("StepBar"),d=e("ClientOnly"),r=e("el-card");return h(),c("div",null,[s[2]||(s[2]=i('<h1 id="تطوير-نظام-الامتحانات-عبر-الإنترنت-والإدارة-—-تطبيق-عملي" tabindex="-1">تطوير نظام الامتحانات عبر الإنترنت والإدارة — تطبيق عملي <a class="header-anchor" href="#تطوير-نظام-الامتحانات-عبر-الإنترنت-والإدارة-—-تطبيق-عملي" aria-label="Permalink to “تطوير نظام الامتحانات عبر الإنترنت والإدارة — تطبيق عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب هذا المشروع <strong>التطبيقي</strong> منك العمل وفق مستند متطلبات منتج (PRD) حقيقي، لبناء نظام امتحانات عبر الإنترنت وإدارة من الصفر. ما يميز هذا المشروع هو أنه يتضمن أدوارًا متعددة (طالب ومسؤول)، حيث يرى كل دور صفحات مختلفة ويمكنه تنفيذ عمليات مختلفة. ستستخدم Express لبناء الخلفية وتنفيذ سلسلة أعمال الامتحانات الكاملة.</p><p>هذا هو المشروع <strong>التطبيقي</strong> الشامل في المرحلة الثانية. أنظمة الصلاحيات متعددة الأدوار شائعة جدًا في العمل الفعلي، وبعد إتقان هذا النموذج، ستتمكن من التعامل مع سيناريوهات أعمال متنوعة مثل التعليم والتدريب و SaaS وإدارة الخلفية.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات المستخدم واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">مكتبة المكونات الحديثة</a>)</li><li>تصميم وتطوير واجهات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع <strong>التطبيقي</strong>، ستتمكن من:</p><ol><li>قراءة وفهم مستند PRD حقيقي واستخراج قائمة مهام التطوير منه</li><li>تصميم التحكم في صلاحيات نظام متعدد الأدوار وتوجيه الصفحات</li><li>استخدام Express لتنفيذ واجهات API خلفية كاملة</li><li>تنفيذ سلسلة أعمال الامتحانات والتقديم والتصحيح التلقائي</li><li>إكمال التكامل الشامل من البداية للنهاية وتسليم نموذج أولي لنظام أعمال قابل للعرض</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستقوم ببنائه هو نظام امتحانات عبر الإنترنت وإدارة، يتضمن ثلاثة أنظمة فرعية:</p><table tabindex="0"><thead><tr><th>النظام الفرعي</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>موقع الشركة</strong></td><td>تقديم المنصة، مدخل تسجيل الدخول</td></tr><tr><td><strong>جانب الطالب</strong></td><td>قائمة الامتحانات، الإجابة، التقديم، عرض الدرجات</td></tr><tr><td><strong>لوحة الإدارة</strong></td><td>إدارة بنك الأسئلة، إدارة الامتحانات، سجلات التقديم، إحصائيات الدرجات</td></tr></tbody></table><p>تستخدم الخلفية Express، وتحتاج إلى دعم: مصادقة تسجيل الدخول، صلاحيات الأدوار، إدارة الامتحانات وبنك الأسئلة، عملية التقديم والتصحيح التلقائي، إدارة الدرجات والإحصائيات.</p><div class="tip custom-block"><p class="custom-block-title">رابط مستند PRD</p><p>مستند متطلبات هذا المشروع على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/exam-management-express/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',15)),a("div",u,[l(d,null,{default:t(()=>[l(p,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD، توضيح الأدوار والصفحات وسلسلة الامتحانات ونموذج البيانات"},{title:"بناء الهيكل",description:"استخدام AI لتوليد هيكل صفحات جانب الطالب والإدارة"},{title:"تطوير الخلفية",description:"Express يربط تسجيل الدخول والامتحانات والتقديم والتصحيح"},{title:"التكامل والنشر",description:"تشغيل شامل من البداية للنهاية، نشر والتحضير للعرض"}]})]),_:1})]),s[3]||(s[3]=i(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركّز على الإجابة عن الأسئلة التالية:</p><ul><li>كم دورًا يتضمن النظام؟ وماذا يمكن لكل دور أن يفعل؟</li><li>هل قائمة الصفحات مكتملة؟ ما هي الصفحات في جانب الطالب وجانب الإدارة؟</li><li>ما أنواع الأسئلة المدعومة؟ وما هو منطق التصحيح لكل نوع؟</li><li>ما هي العملية الكاملة للامتحان؟ (النشر ← البدء ← الإجابة ← التقديم ← التصحيح ← عرض الدرجات)</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ بكتابة الكود. عدم وضوح المتطلبات هو السبب الأكثر شيوعًا لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><p>استنادًا إلى PRD، استخلص البنية العامة للنظام:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;موقع الشركة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; student[&quot;جانب الطالب&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;لوحة الإدارة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; auth[&quot;المصادقة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; exam[&quot;الامتحانات والإجابة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exam --&gt; db[&quot;قاعدة البيانات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; question[&quot;إدارة بنك الأسئلة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; submission[&quot;سجلات التقديم وإحصائيات الدرجات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  question --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  submission --&gt; db</span></span></code></pre></div><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-توليد-الصفحات-الأمامية" tabindex="-1">2.1 توليد الصفحات الأمامية <a class="header-anchor" href="#_2-1-توليد-الصفحات-الأمامية" aria-label="Permalink to “2.1 توليد الصفحات الأمامية”">​</a></h3><p>مرجع <strong>للنصيحة</strong>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني بناءً على PRD الحالي في توليد هيكل أمامي لنظام امتحانات عبر الإنترنت وإدارة.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>حزم التقنيات المطلوبة:</span></span>
<span class="line"><span>- Next.js App Router</span></span>
<span class="line"><span>- TypeScript</span></span>
<span class="line"><span>- Tailwind CSS</span></span>
<span class="line"><span>- shadcn/ui</span></span>
<span class="line"><span></span></span>
<span class="line"><span>قائمة الصفحات:</span></span>
<span class="line"><span>1. الصفحة الرئيسية /</span></span>
<span class="line"><span>2. صفحة تسجيل الدخول /login</span></span>
<span class="line"><span>3. قائمة امتحانات الطالب /student/exams</span></span>
<span class="line"><span>4. صفحة إجابة الطالب /student/exams/[id]</span></span>
<span class="line"><span>5. صفحة درجات الطالب /student/history</span></span>
<span class="line"><span>6. الصفحة الرئيسية للإدارة /admin</span></span>
<span class="line"><span>7. صفحة إدارة الامتحانات /admin/exams</span></span>
<span class="line"><span>8. صفحة إدارة بنك الأسئلة /admin/questions</span></span>
<span class="line"><span>9. صفحة سجلات التقديم /admin/submissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>- صفحات جانب الطالب تؤكد على الوضوح والتركيز وسهولة الإجابة</span></span>
<span class="line"><span>- صفحات جانب الإدارة تستخدم تخطيط شريط جانبي + شريط علوي</span></span>
<span class="line"><span>- استخدم بيانات وهمية أولاً بدون ربط واجهات حقيقية</span></span>
<span class="line"><span>- **لاحظ** التوافق الأساسي مع سطح المكتب والأجهزة المحمولة</span></span></code></pre></div><h3 id="_2-2-تحسين-صفحة-إجابة-الطالب" tabindex="-1">2.2 تحسين صفحة إجابة الطالب <a class="header-anchor" href="#_2-2-تحسين-صفحة-إجابة-الطالب" aria-label="Permalink to “2.2 تحسين صفحة إجابة الطالب”">​</a></h3><p>صفحة الإجابة هي الصفحة الأساسية في جانب الطالب، ركّز على تحسينها:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في تحسين صفحة إجابة الطالب.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>هذه صفحة إجابة في نظام امتحانات عبر الإنترنت، تحتاج إلى تضمين:</span></span>
<span class="line"><span>- عرض عنوان الامتحان والعد التنازلي وعدد الأسئلة المُجاب عليها في الأعلى</span></span>
<span class="line"><span>- عرض نص السؤال والخيارات في الوسط</span></span>
<span class="line"><span>- دعم ثلاثة أنواع أسئلة: اختيار من متعدد، صح/خطأ، إجابة قصيرة</span></span>
<span class="line"><span>- بطاقة إجابة على اليسار أو الأعلى تعرض حالة الإجابة لكل سؤال</span></span>
<span class="line"><span>- مربع تأكيد قبل النقر على التقديم</span></span>
<span class="line"><span></span></span>
<span class="line"><span>استخدم بيانات وهمية لتحقيق التفاعل أولاً بدون ربط واجهات حقيقية.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>- واجهة بسيطة، لا تشبه صفحة جدول الإدارة</span></span>
<span class="line"><span>- عد تنازلي بارز لكن بدون ضغط مبالغ فيه</span></span>
<span class="line"><span>- توجد حالة فارغة وحالة تحميل</span></span></code></pre></div><h3 id="_2-3-تحسين-لوحة-الإدارة-الخلفية" tabindex="-1">2.3 تحسين لوحة الإدارة الخلفية <a class="header-anchor" href="#_2-3-تحسين-لوحة-الإدارة-الخلفية" aria-label="Permalink to “2.3 تحسين لوحة الإدارة الخلفية”">​</a></h3><p>تركز النسخة الأولى من لوحة الإدارة على ثلاث مناطق أساسية:</p><ul><li><strong>إدارة الامتحانات</strong>: إنشاء امتحان، تعيين المدة، حالة النشر</li><li><strong>إدارة بنك الأسئلة</strong>: إضافة أسئلة، تعديل أسئلة، فرز حسب نوع السؤال</li><li><strong>سجلات التقديم</strong>: عرض تقديمات الطلاب والدرجات والوقت</li></ul><h3 id="_2-4-التحقق-من-بنية-الصفحات" tabindex="-1">2.4 التحقق من بنية الصفحات <a class="header-anchor" href="#_2-4-التحقق-من-بنية-الصفحات" aria-label="Permalink to “2.4 التحقق من بنية الصفحات”">​</a></h3><p>تحقق من كل عنصر:</p><ul><li>[ ] هل مدخلا جانب الطالب والإدارة منفصلان</li><li>[ ] هل صفحة تسجيل الدخول وقائمة الامتحانات وصفحة الإجابة وصفحة الدرجات مكتملة</li><li>[ ] هل صفحات بنك الأسئلة وإدارة الامتحانات وسجلات التقديم في جانب الإدارة قابلة للوصول</li><li>[ ] هل يوجد فرق واضح في نمط الصفحات بين جانب الطالب وجانب الإدارة</li></ul><h3 id="هل-واجهتك-عقبات؟" tabindex="-1">هل واجهتك عقبات؟ <a class="header-anchor" href="#هل-واجهتك-عقبات؟" aria-label="Permalink to “هل واجهتك عقبات؟”">​</a></h3><p>إذا واجهتك صعوبة في مرحلة بناء الواجهة الأمامية، يمكنك مراجعة هذه الفصول:</p><ul><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">تصميم وتطوير واجهات الخلفية للتطبيقات</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام مكتبة مكونات حديثة</a></li></ul><h2 id="الجزء-الثالث-تطوير-الخلفية" tabindex="-1">الجزء الثالث: تطوير الخلفية <a class="header-anchor" href="#الجزء-الثالث-تطوير-الخلفية" aria-label="Permalink to “الجزء الثالث: تطوير الخلفية”">​</a></h2><h3 id="_3-1-تسجيل-الدخول-والتحكم-في-الصلاحيات" tabindex="-1">3.1 تسجيل الدخول والتحكم في الصلاحيات <a class="header-anchor" href="#_3-1-تسجيل-الدخول-والتحكم-في-الصلاحيات" aria-label="Permalink to “3.1 تسجيل الدخول والتحكم في الصلاحيات”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني في إكمال تسجيل الدخول والتحكم في الصلاحيات لنظام الامتحانات عبر الإنترنت.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>الخلفية تستخدم Express.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>الأهداف:</span></span>
<span class="line"><span>1. يمكن للطالب والمسؤول تسجيل الدخول</span></span>
<span class="line"><span>2. يُعاد دور المستخدم بعد تسجيل الدخول</span></span>
<span class="line"><span>3. يمكن للطالب فقط الوصول إلى واجهات /student/*</span></span>
<span class="line"><span>4. يمكن للمسؤول فقط الوصول إلى واجهات /admin/*</span></span>
<span class="line"><span>5. يُعاد توجيه المستخدمين غير المسجلين إلى /login عند محاولة الوصول للصفحات المحمية</span></span>
<span class="line"><span></span></span>
<span class="line"><span>متطلبات التنفيذ:</span></span>
<span class="line"><span>- اقترح هيكل دليل واضح</span></span>
<span class="line"><span>- اشرح بوضوح مسؤوليات الوسائط</span></span>
<span class="line"><span>- لا تقم بتشفير المتغيرات البيئية بشكل ثابت</span></span>
<span class="line"><span>- بعد الانتهاء اشرح كيفية التحقق من أن الصلاحيات تعمل</span></span></code></pre></div><h3 id="_3-2-واجهات-إدارة-الامتحانات-وبنك-الأسئلة" tabindex="-1">3.2 واجهات إدارة الامتحانات وبنك الأسئلة <a class="header-anchor" href="#_3-2-واجهات-إدارة-الامتحانات-وبنك-الأسئلة" aria-label="Permalink to “3.2 واجهات إدارة الامتحانات وبنك الأسئلة”">​</a></h3><p>يُنصح بالتنفيذ حسب الوحدات التالية:</p><table tabindex="0"><thead><tr><th>الوحدة</th><th>الواجهات المقترحة</th></tr></thead><tbody><tr><td>إدارة الامتحانات</td><td><code>GET /api/exams</code>، <code>POST /api/admin/exams</code>، <code>PATCH /api/admin/exams/:id</code></td></tr><tr><td>إدارة بنك الأسئلة</td><td><code>GET /api/admin/questions</code>، <code>POST /api/admin/questions</code></td></tr><tr><td>بدء الامتحان</td><td><code>POST /api/submissions/start</code></td></tr><tr><td>تقديم ورقة الامتحان</td><td><code>POST /api/submissions/:id/submit</code></td></tr><tr><td>سجل الدرجات</td><td><code>GET /api/student/history</code>، <code>GET /api/admin/submissions</code></td></tr></tbody></table><p>مرجع <strong>للنصيحة</strong>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في تصميم وتنفيذ Express API لنظام الامتحانات عبر الإنترنت.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>نطاق الوظائف:</span></span>
<span class="line"><span>- المسؤول ينشئ امتحانات</span></span>
<span class="line"><span>- المسؤول يدير بنك الأسئلة</span></span>
<span class="line"><span>- الطالب يعرض الامتحانات المنشورة</span></span>
<span class="line"><span>- الطالب يبدأ الامتحان وينشئ تقديمًا</span></span>
<span class="line"><span>- الطالب يقدم الإجابات ويتم التصحيح التلقائي للأسئلة الموضوعية</span></span>
<span class="line"><span>- أسئلة الإجابة القصيرة تُعلَّم كقيد المراجعة أولًا</span></span>
<span class="line"><span>- الطالب يعرض درجاته التاريخية</span></span>
<span class="line"><span>- المسؤول يعرض جميع سجلات التقديم</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>- تسمية واضحة للواجهات</span></span>
<span class="line"><span>- إرجاع بنية JSON موحدة</span></span>
<span class="line"><span>- فصل controller و service و middleware و db في الكود</span></span>
<span class="line"><span>- شرح كيفية اختبار كل واجهة</span></span></code></pre></div><h3 id="_3-3-منطق-التصحيح" tabindex="-1">3.3 منطق التصحيح <a class="header-anchor" href="#_3-3-منطق-التصحيح" aria-label="Permalink to “3.3 منطق التصحيح”">​</a></h3><p>منطق التصحيح هو قاعدة الأعمال الأساسية في نظام الامتحانات:</p><ul><li><strong>أسئلة الاختيار من متعدد</strong>: يُحصل الطالب على النقاط إذا تطابقت إجابته مع الإجابة النموذجية</li><li><strong>أسئلة الصح/الخطأ</strong>: يمكن تصحيحها تلقائيًا أيضًا</li><li><strong>أسئلة الإجابة القصيرة</strong>: في الإصدار الأول يتم حفظ الإجابة فقط بدون درجة، مع حالة <code>reviewed = false</code></li></ul><div class="tip custom-block"><p class="custom-block-title">عنصر إضافي</p><p>إذا أردت إضافة قدرات الذكاء الاصطناعي، يمكنك السماح للمسؤول بإدخال &quot;الموضوع + الصعوبة&quot; في لوحة الإدارة، ثم يقوم النموذج بتوليد مجموعة من الأسئلة المرشحة أولًا، ثم تتم مراجعتها يدويًا وإضافتها إلى بنك الأسئلة. لكن هذا عنصر إضافي وليس مطلوبًا.</p></div><h2 id="الجزء-الرابع-التكامل-والنشر" tabindex="-1">الجزء الرابع: التكامل والنشر <a class="header-anchor" href="#الجزء-الرابع-التكامل-والنشر" aria-label="Permalink to “الجزء الرابع: التكامل والنشر”">​</a></h2><h3 id="_4-1-اختبار-شامل-من-البداية-للنهاية" tabindex="-1">4.1 اختبار شامل من البداية للنهاية <a class="header-anchor" href="#_4-1-اختبار-شامل-من-البداية-للنهاية" aria-label="Permalink to “4.1 اختبار شامل من البداية للنهاية”">​</a></h3><p>تحقق من السيناريوهات التالية على الأقل:</p><ul><li>تسجيل دخول الطالب ← عرض قائمة الامتحانات ← بدء الإجابة ← التقديم ← عرض الدرجات</li><li>تسجيل دخول المسؤول ← إنشاء امتحان ← إضافة أسئلة ← النشر ← عرض سجلات التقديم</li></ul><h3 id="_4-2-النشر" tabindex="-1">4.2 النشر <a class="header-anchor" href="#_4-2-النشر" aria-label="Permalink to “4.2 النشر”">​</a></h3><ul><li>نشر الواجهة الأمامية على Vercel / Zeabur</li><li>نشر Express API على Zeabur / Railway / Render</li><li>استخدام Supabase Postgres أو PostgreSQL مُدار لقاعدة البيانات</li></ul><p>فحوصات ما قبل النشر:</p><ul><li>[ ] هل متغيرات البيئة مكتملة</li><li>[ ] هل عناوين API للواجهة الأمامية والخلفية صحيحة</li><li>[ ] هل حالة تسجيل الدخول تعمل في بيئة الإنتاج</li><li>[ ] هل يمكن لحساب المسؤول الوصول فعليًا إلى لوحة الإدارة</li><li>[ ] هل يحتوي README على تعليمات التشغيل والنشر والاختبار</li></ul><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض تجريبي عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (مع README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الأساسية (الصفحة الرئيسية، قائمة امتحانات الطالب، صفحة الإجابة، لوحة الإدارة)</li><li>[ ] فيديو عرض تجريبي مدته 60 ثانية (يغطي عملية إجابة الطالب وعملية إدارة المسؤول)</li></ul><p>يجب أن يحتوي README على الأقل: <strong>مقدمة المشروع</strong>، شرح الصفحات الأساسية، حزم التقنيات، <strong>خطوات</strong> التشغيل المحلي، قائمة متغيرات البيئة.</p><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>اكتمال الصفحات</td><td>الصفحات الرئيسية لجانب الطالب والإدارة قابلة للوصول</td><td>نمط الصفحات موحد، والتوافق الأساسي مع الأجهزة المحمولة</td></tr><tr><td>حلقة الأعمال</td><td>يمكن للطالب تسجيل الدخول والمشاركة في الامتحان والتقديم وعرض الدرجات</td><td>يمكن للمسؤول إنشاء ونشر امتحان بالكامل</td></tr><tr><td>صحة البيانات</td><td>تُكتب الإجابات المقدمة في قاعدة البيانات والأسئلة الموضوعية تُصحح تلقائيًا</td><td>أسئلة الإجابة القصيرة تدعم المراجعة اليدوية أو المساعدة بالذكاء الاصطناعي</td></tr><tr><td>التحكم في الصلاحيات</td><td>حدود وصول الطالب والمسؤول واضحة</td><td>واجهات الخادم لديها أيضًا تحقق من الأدوار</td></tr><tr><td>جودة التسليم</td><td>المشروع قابل للتشغيل والنشر و README واضح</td><td>يوجد فيديو عرض تجريبي وتعليمات اختبار</td></tr></tbody></table><h2 id="فحوصات-ما-قبل-التقديم" tabindex="-1">فحوصات ما قبل التقديم <a class="header-anchor" href="#فحوصات-ما-قبل-التقديم" aria-label="Permalink to “فحوصات ما قبل التقديم”">​</a></h2>`,51)),l(r,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...s[0]||(s[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"نظرة أخيرة قبل التقديم",-1)])]),default:t(()=>[s[1]||(s[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" الصفحة الرئيسية وتسجيل الدخول وجانب الطالب وجانب الإدارة **مكتملة** جميعها")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" يمكن للطالب بدء الامتحان وتقديم الإجابات بشكل طبيعي")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" يمكن للمسؤول إنشاء امتحان وعرض سجلات التقديم")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" درجات الأسئلة الموضوعية تُحسب تلقائيًا وتُكتب في قاعدة البيانات")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" تم التحقق من حدود صلاحيات الطالب والمسؤول")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" تم نشر المشروع أو لديه تعليمات تشغيل محلي كاملة")])])],-1))]),_:1}),s[4]||(s[4]=i('<h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام مكتبة مكونات حديثة</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات والتوثيق بمساعدة النماذج الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li></ul>',2))])}const y=o(b,[["render",g]]);export{P as __pageData,y as default};
